_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw")

class ModelNew(nn.Module):
    """
    Performs a standard 2D convolution operation with square input and asymmetric kernel, with dilation and padding.
    Re-implements the forward path using a custom PTX kernel while retaining a nn.Conv2d module to host parameters.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        # Retain a Conv2d module only to store parameters (weight/bias) and metadata; not used for computation.
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)

        # Cache scalar hyperparameters for quick kernel argument preparation.
        if isinstance(kernel_size, tuple):
            self.kh, self.kw = int(kernel_size[0]), int(kernel_size[1])
        else:
            self.kh = self.kw = int(kernel_size)
        self.stride = int(stride)
        self.pad_h, self.pad_w = int(padding[0]), int(padding[1])
        self.dil_h, self.dil_w = int(dilation[0]), int(dilation[1])

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        w = self.conv2d.weight
        b = self.conv2d.bias
        assert w.is_contiguous(), "Weight must be contiguous"
        if b is not None:
            assert b.is_contiguous(), "Bias must be contiguous"

        N, Cin, H, W = x.shape
        Cout, Cin_w, KH, KW = w.shape
        assert Cin == Cin_w and KH == self.kh and KW == self.kw, "Mismatched shapes"

        # Output dimensions per PyTorch Conv2d formula
        OH = (H + 2 * self.pad_h - self.dil_h * (KH - 1) - 1) // self.stride + 1
        OW = (W + 2 * self.pad_w - self.dil_w * (KW - 1) - 1) // self.stride + 1

        y = torch.empty((N, Cout, OH, OW), device=x.device, dtype=x.dtype)

        mod = _get_ptx_module()
        func_name = "conv2d_nchw"

        block_x = 16
        block_y = 16
        grid_x = (OW + block_x - 1) // block_x
        grid_y = (OH + block_y - 1) // block_y
        grid_z = N * Cout

        bias_arg = b if b is not None else u64(0)

        mod.launch(
            func_name,
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x,
                w,
                bias_arg,
                y,
                i32(N),
                i32(Cin),
                i32(H),
                i32(W),
                i32(Cout),
                i32(KH),
                i32(KW),
                i32(self.stride),
                i32(self.pad_h),
                i32(self.pad_w),
                i32(self.dil_h),
                i32(self.dil_w),
                i32(OH),
                i32(OW),
            ],
            shared_memory=max(128, ((self.kw + 31) & ~31) * 4),
            stream=torch.cuda.current_stream(x.device),
        )
        return y

