    ld.param.u32    %r10, [pN];
    ld.param.u32    %r11, [pCin];
    ld.param.u32    %r12, [pH];
    ld.param.u32    %r13, [pW];
    ld.param.u32    %r14, [pCout];
    ld.param.u32    %r15, [pKH];
    ld.param.u32    %r16, [pKW];
    ld.param.u32    %r17, [pStride];
    ld.param.u32    %r18, [pPadH];
    ld.param.u32    %r19, [pPadW];
    ld.param.u32    %r20, [pDilH];
    ld.param.u32    %r21, [pDilW];
    ld.param.u32    %r22, [pOH];
    ld.param.u32    %r23, [pOW];
    // Thread/block indices
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %tid.y;
    mov.u32         %r32, %ctaid.x;
    mov.u32         %r33, %ctaid.y;
    mov.u32         %r34, %ctaid.z;
    mov.u32         %r35, %ntid.x;
    mov.u32         %r36, %ntid.y;
    // ow = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32      %r40, %r32, %r35, %r30;
    // oh = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.s32      %r41, %r33, %r36, %r31;
    // Decompose blockIdx.z into (n, oc)
    // q = blockIdx.z / Cout; r = blockIdx.z - q*Cout
    div.u32         %r42, %r34, %r14;     // n
    mul.lo.u32      %r43, %r42, %r14;     // q*Cout
    sub.s32         %r44, %r34, %r43;     // oc
    // Bounds check for ow, oh, n, oc -> build active predicate (no early exit due to barriers)
    setp.ge.u32     %p0, %r40, %r23;
    setp.ge.u32     %p1, %r41, %r22;
    or.pred         %p2, %p0, %p1;
    setp.ge.u32     %p3, %r42, %r10;
    or.pred         %p4, %p2, %p3;
    setp.ge.u32     %p5, %r44, %r14;
    or.pred         %p6, %p4, %p5;        // p6 = invalid
    not.pred        %p16, %p6;            // p16 = active
    // Precompute common 64-bit products
    cvt.u64.u32     %rd20, %r12;          // H
    cvt.u64.u32     %rd21, %r13;          // W
    mul.lo.u64      %rd22, %rd20, %rd21;  // HW
    cvt.u64.u32     %rd23, %r11;          // Cin
    mul.lo.u64      %rd24, %rd23, %rd22;  // Cin * HW
    cvt.u64.u32     %rd25, %r22;          // OH
    cvt.u64.u32     %rd26, %r23;          // OW
    mul.lo.u64      %rd27, %rd25, %rd26;  // OH * OW
    cvt.u64.u32     %rd28, %r15;          // KH
    cvt.u64.u32     %rd29, %r16;          // KW
    mul.lo.u64      %rd30, %rd28, %rd29;  // KH * KW
    // Base for input: baseN = n * (Cin*HW)
    cvt.u64.u32     %rd31, %r42;          // n
    mul.lo.u64      %rd32, %rd31, %rd24;  // baseN
    // Base for output linear index
    // out_index = (((n*Cout + oc)*OH + oh)*OW + ow)
    // t0 = n*Cout + oc
    cvt.u64.u32     %rd33, %r14;          // Cout
    mul.lo.u64      %rd34, %rd31, %rd33;  // n*Cout
    cvt.u64.u32     %rd35, %r44;          // oc
    add.u64         %rd36, %rd34, %rd35;  // n*Cout + oc
    // t1 = t0 * (OH*OW)
    mul.lo.u64      %rd37, %rd36, %rd27;  // (n*Cout+oc)*OH*OW
    // t2 = oh*OW + ow
    cvt.u64.u32     %rd38, %r41;          // oh
    mul.lo.u64      %rd39, %rd38, %rd26;  // oh*OW
    cvt.u64.u32     %rd60, %r40;          // ow
    add.u64         %rd61, %rd39, %rd60;  // oh*OW + ow
    // out_index = t1 + t2
    add.u64         %rd62, %rd37, %rd61;
    shl.b64         %rd63, %rd62, 2;      // * sizeof(float)
    add.u64         %rd64, %rd13, %rd63;  // out_ptr + offset
    // sum = bias[oc] or 0
    mov.f32         %f0, 0f00000000;
    setp.ne.u64     %p7, %rd12, 0;
    @!%p7 bra       NO_BIAS;
    {
         shl.b64     %rd65, %rd35, 2;     // oc * 4
         add.u64     %rd40, %rd12, %rd65;
         ld.global.f32 %f0, [%rd40];
    }
NO_BIAS:
    // Precompute base_oh = oh*stride - pad_h (signed)
    mul.lo.s32      %r50, %r41, %r17;     // oh*stride
    sub.s32         %r50, %r50, %r18;     // base_oh
    // base_ow = ow*stride - pad_w
    mul.lo.s32      %r51, %r40, %r17;     // ow*stride
    sub.s32         %r51, %r51, %r19;     // base_ow
    // Prepare constants for loops
    cvt.u64.u32     %rd41, %r20;          // dil_h
    cvt.u64.u32     %rd42, %r21;          // dil_w
    cvt.u64.u32     %rd43, %r16;          // KW (u64)
    cvt.u64.u32     %rd44, %r12;          // H (u64 reuse)
    cvt.u64.u32     %rd45, %r13;          // W (u64 reuse)
    // Linear thread id and block size for cooperative weight load
    mad.lo.s32      %r70, %r31, %r35, %r30;   // linear tid
    mul.lo.s32      %r71, %r35, %r36;        // block size
    mov.u64         %rd72, s;            // shared base
    // Outer loop over Cin: rc = 0
    mov.u32         %r60, 0;
L_C_LOOP:
    setp.ge.u32     %p8, %r60, %r11;
    @%p8 bra        L_C_DONE;
    // base_in_c = baseN + rc * HW
    cvt.u64.u32     %rd46, %r60;
    mul.lo.u64      %rd47, %rd46, %rd22;      // rc*HW
    add.u64         %rd48, %rd32, %rd47;      // base_in_c
    // base_w_c = ((oc * Cin) + rc) * (KH*KW)
    mul.lo.u64      %rd49, %rd35, %rd23;      // oc * Cin
    add.u64         %rd66, %rd49, %rd46;      // oc*Cin + rc
    mul.lo.u64      %rd67, %rd66, %rd30;      // * (KH*KW)
    // Cooperative load of weights for this rc into shared memory
    mul.lo.u32      %r72, %r15, %r16;        // w_count
    mov.u32         %r73, %r70;              // idx = linear tid
L_WCPY_LOOP:
    setp.ge.u32     %p17, %r73, %r72;
    @%p17 bra       L_WCPY_DONE;
    cvt.u64.u32     %rd73, %r73;
    add.u64         %rd74, %rd67, %rd73;     // base_w_c + idx
    shl.b64         %rd75, %rd74, 2;
    add.u64         %rd76, %rd11, %rd75;
    ld.global.f32   %f3, [%rd76];
    shl.b32         %r74, %r73, 2;
    cvt.u64.u32     %rd77, %r74;
    add.u64         %rd78, %rd72, %rd77;
    st.shared.f32   [%rd78], %f3;
    add.u32         %r73, %r73, %r71;
    bra             L_WCPY_LOOP;
L_WCPY_DONE:
    bar.sync 0;
    // Inactive threads skip compute but must join barrier each rc
    @!%p16 bra      L_C_BARRIER_RC;
    // Loop over kh: rkh = 0
    mov.u32         %r61, 0;
L_KH_LOOP:
    setp.ge.u32     %p9, %r61, %r15;
    @%p9 bra        L_KH_DONE;
    // ih = base_oh + rkh * dil_h (signed)
    mul.lo.s32      %r62, %r61, %r20;
    add.s32         %r63, %r50, %r62;        // ih (s32)
    // if !(0 <= ih < H) skip KW loop
    setp.lt.s32     %p11, %r63, 0;
    setp.ge.s32     %p12, %r63, %r12;
    or.pred         %p13, %p11, %p12;
    @%p13 bra       L_KW_SKIP;
    // ih_u64 * W
    cvt.u64.s32     %rd68, %r63;
    mul.lo.u64      %rd69, %rd68, %rd21;     // ih * W
    // base_w_ckh = base_w_c + rkh * KW (not used for shared ld, kept for minimal changes)
    cvt.u64.u32     %rd70, %r61;
    mul.lo.u64      %rd71, %rd70, %rd43;
    add.u64         %rd50, %rd67, %rd71;
    // Loop over kw: rkw = 0
    mov.u32         %r64, 0;
L_KW_LOOP:
    setp.ge.u32     %p14, %r64, %r16;
    @%p14 bra       L_KW_DONE;
    // iw = base_ow + rkw * dil_w (signed)
    mul.lo.s32      %r65, %r64, %r21;      // rkw * dil_w
    add.s32         %r66, %r51, %r65;      // base_ow + rkw*dil_w
    // if !(0 <= iw < W) skip accumulate
    setp.lt.s32     %p11, %r66, 0;
    setp.ge.s32     %p12, %r66, %r13;
    or.pred         %p10, %p11, %p12;
    @%p10 bra       L_KW_NEXT;
    // input index: base_in_c + ih*W + iw
    cvt.u64.s32     %rd51, %r66;             // iw
    add.u64         %rd52, %rd69, %rd51;     // ih*W + iw
    add.u64         %rd53, %rd48, %rd52;     // + base_in_c
    shl.b64         %rd54, %rd53, 2;
    add.u64         %rd55, %rd10, %rd54;
    ld.global.f32   %f1, [%rd55];
    // weight from shared: idx = rkh*KW + rkw
    mul.lo.u32      %r75, %r61, %r16;
    add.u32         %r76, %r75, %r64;
    shl.b32         %r77, %r76, 2;
    cvt.u64.u32     %rd79, %r77;
    add.u64         %rd78, %rd72, %rd79;
    ld.shared.f32   %f2, [%rd78];
    // sum += in * w
    fma.rn.f32      %f0, %f1, %f2, %f0;
L_KW_NEXT:
    add.s32         %r64, %r64, 1;
    bra             L_KW_LOOP;
L_KW_DONE:
L_KW_SKIP:
    add.s32         %r61, %r61, 1;
    bra             L_KH_LOOP;
L_KH_DONE:
    // end of KH loop for this rc -> go to barrier
    bra             L_C_BARRIER_RC;
L_C_BARRIER_RC:
    bar.sync 0;
    add.s32         %r60, %r60, 1;
    bra             L_C_LOOP;
L_C_DONE:
    // Store result (only if active thread)
    @!%p16 bra      NO_STORE;
    st.global.f32   [%rd64], %f0;
NO_STORE:
END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw")

class ModelNew(nn.Module):
    """
    Performs a standard 2D convolution operation with square input and asymmetric kernel, with dilation and padding.
    Re-implements the forward path using a custom PTX kernel while retaining a nn.Conv2d module to host parameters.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        # Retain a Conv2d module only to store parameters (weight/bias) and metadata; not used for computation.
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)

        # Cache scalar hyperparameters for quick kernel argument preparation.
        if isinstance(kernel_size, tuple):
            self.kh, self.kw = int(kernel_size[0]), int(kernel_size[1])
        else:
            self.kh = self.kw = int(kernel_size)
        self.stride = int(stride)
        self.pad_h, self.pad_w = int(padding[0]), int(padding[1])
        self.dil_h, self.dil_w = int(dilation[0]), int(dilation[1])

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        w = self.conv2d.weight
        b = self.conv2d.bias
        assert w.is_contiguous(), "Weight must be contiguous"
        if b is not None:
            assert b.is_contiguous(), "Bias must be contiguous"

        N, Cin, H, W = x.shape
        Cout, Cin_w, KH, KW = w.shape
        assert Cin == Cin_w and KH == self.kh and KW == self.kw, "Mismatched shapes"

        # Output dimensions per PyTorch Conv2d formula
        OH = (H + 2 * self.pad_h - self.dil_h * (KH - 1) - 1) // self.stride + 1
        OW = (W + 2 * self.pad_w - self.dil_w * (KW - 1) - 1) // self.stride + 1

        y = torch.empty((N, Cout, OH, OW), device=x.device, dtype=x.dtype)

        mod = _get_ptx_module()
        func_name = "conv2d_nchw"

        block_x = 16
        block_y = 16
        grid_x = (OW + block_x - 1) // block_x
        grid_y = (OH + block_y - 1) // block_y
        grid_z = N * Cout

        bias_arg = b if b is not None else u64(0)

        mod.launch(
            func_name,
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x,
                w,
                bias_arg,
                y,
                u32(N),
                u32(Cin),
                u32(H),
                u32(W),
                u32(Cout),
                u32(KH),
                u32(KW),
                u32(self.stride),
                u32(self.pad_h),
                u32(self.pad_w),
                u32(self.dil_h),
                u32(self.dil_w),
                u32(OH),
                u32(OW),
            ],
            shared_memory=KH * KW * 4,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
